-- Atomic event aggregates and download ledger. Apply after the historical import.

CREATE INDEX skill_events_by_skill_time ON skill_events(skill_slug,created_at);

CREATE INDEX skill_feedback_by_skill_time ON skill_feedback(skill_slug,created_at);

CREATE INDEX agent_outcomes_by_skill_time ON agent_outcomes(skill_slug,created_at);

CREATE TRIGGER skill_event_stats_insert AFTER INSERT ON skill_events BEGIN
 INSERT INTO skill_event_stats(skill_slug,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,last_event_at,updated_at) VALUES (NEW.skill_slug,1,NEW.event_type IN ('view'),NEW.event_type IN ('install_copy'),NEW.event_type IN ('save'),NEW.event_type IN ('compare'),NEW.event_type IN ('outbound_github','outbound_docs'),NEW.event_type IN ('claim_start'),NEW.event_type IN ('claim_submit'),NEW.event_type IN ('resolve_request'),NEW.event_type IN ('install_start'),NEW.event_type IN ('install_success'),NEW.event_type IN ('install_failure'),NEW.event_type IN ('agent_call'),NEW.event_type IN ('outcome_success'),NEW.event_type IN ('outcome_failure'),NEW.event_type IN ('share_copy'),NEW.created_at,(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')) ON CONFLICT(skill_slug) DO UPDATE SET total_events=skill_event_stats.total_events+excluded.total_events,views=skill_event_stats.views+excluded.views,install_copies=skill_event_stats.install_copies+excluded.install_copies,saves=skill_event_stats.saves+excluded.saves,compares=skill_event_stats.compares+excluded.compares,outbound_clicks=skill_event_stats.outbound_clicks+excluded.outbound_clicks,claim_starts=skill_event_stats.claim_starts+excluded.claim_starts,claim_submits=skill_event_stats.claim_submits+excluded.claim_submits,resolve_requests=skill_event_stats.resolve_requests+excluded.resolve_requests,install_starts=skill_event_stats.install_starts+excluded.install_starts,install_successes=skill_event_stats.install_successes+excluded.install_successes,install_failures=skill_event_stats.install_failures+excluded.install_failures,agent_calls=skill_event_stats.agent_calls+excluded.agent_calls,outcome_successes=skill_event_stats.outcome_successes+excluded.outcome_successes,outcome_failures=skill_event_stats.outcome_failures+excluded.outcome_failures,share_copies=skill_event_stats.share_copies+excluded.share_copies,last_event_at=max(coalesce(skill_event_stats.last_event_at,excluded.last_event_at),excluded.last_event_at),updated_at=(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z');
END;

CREATE TRIGGER skill_event_stats_delete AFTER DELETE ON skill_events BEGIN
 DELETE FROM skill_event_stats WHERE skill_slug=OLD.skill_slug;
 INSERT INTO skill_event_stats(skill_slug,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,last_event_at,updated_at) SELECT skill_slug,count(*),sum(event_type IN ('view')),sum(event_type IN ('install_copy')),sum(event_type IN ('save')),sum(event_type IN ('compare')),sum(event_type IN ('outbound_github','outbound_docs')),sum(event_type IN ('claim_start')),sum(event_type IN ('claim_submit')),sum(event_type IN ('resolve_request')),sum(event_type IN ('install_start')),sum(event_type IN ('install_success')),sum(event_type IN ('install_failure')),sum(event_type IN ('agent_call')),sum(event_type IN ('outcome_success')),sum(event_type IN ('outcome_failure')),sum(event_type IN ('share_copy')),max(created_at),(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')
 FROM skill_events WHERE skill_slug=OLD.skill_slug AND EXISTS(SELECT 1 FROM skills WHERE slug=OLD.skill_slug) GROUP BY skill_slug;
END;

CREATE TRIGGER skill_event_stats_update AFTER UPDATE ON skill_events BEGIN
 DELETE FROM skill_event_stats WHERE skill_slug=OLD.skill_slug;
 INSERT INTO skill_event_stats(skill_slug,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,last_event_at,updated_at) SELECT skill_slug,count(*),sum(event_type IN ('view')),sum(event_type IN ('install_copy')),sum(event_type IN ('save')),sum(event_type IN ('compare')),sum(event_type IN ('outbound_github','outbound_docs')),sum(event_type IN ('claim_start')),sum(event_type IN ('claim_submit')),sum(event_type IN ('resolve_request')),sum(event_type IN ('install_start')),sum(event_type IN ('install_success')),sum(event_type IN ('install_failure')),sum(event_type IN ('agent_call')),sum(event_type IN ('outcome_success')),sum(event_type IN ('outcome_failure')),sum(event_type IN ('share_copy')),max(created_at),(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')
 FROM skill_events WHERE skill_slug=OLD.skill_slug AND EXISTS(SELECT 1 FROM skills WHERE slug=OLD.skill_slug) GROUP BY skill_slug;
 DELETE FROM skill_event_stats WHERE skill_slug=NEW.skill_slug;
 INSERT INTO skill_event_stats(skill_slug,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,last_event_at,updated_at) SELECT skill_slug,count(*),sum(event_type IN ('view')),sum(event_type IN ('install_copy')),sum(event_type IN ('save')),sum(event_type IN ('compare')),sum(event_type IN ('outbound_github','outbound_docs')),sum(event_type IN ('claim_start')),sum(event_type IN ('claim_submit')),sum(event_type IN ('resolve_request')),sum(event_type IN ('install_start')),sum(event_type IN ('install_success')),sum(event_type IN ('install_failure')),sum(event_type IN ('agent_call')),sum(event_type IN ('outcome_success')),sum(event_type IN ('outcome_failure')),sum(event_type IN ('share_copy')),max(created_at),(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')
 FROM skill_events WHERE skill_slug=NEW.skill_slug AND EXISTS(SELECT 1 FROM skills WHERE slug=NEW.skill_slug) GROUP BY skill_slug;
END;

CREATE TRIGGER skill_events_daily_insert AFTER INSERT ON skill_events BEGIN
 INSERT INTO skill_events_daily(skill_slug,event_date,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,first_event_at,last_event_at,updated_at) VALUES (NEW.skill_slug,substr(NEW.created_at,1,10),1,NEW.event_type IN ('view'),NEW.event_type IN ('install_copy'),NEW.event_type IN ('save'),NEW.event_type IN ('compare'),NEW.event_type IN ('outbound_github','outbound_docs'),NEW.event_type IN ('claim_start'),NEW.event_type IN ('claim_submit'),NEW.event_type IN ('resolve_request'),NEW.event_type IN ('install_start'),NEW.event_type IN ('install_success'),NEW.event_type IN ('install_failure'),NEW.event_type IN ('agent_call'),NEW.event_type IN ('outcome_success'),NEW.event_type IN ('outcome_failure'),NEW.event_type IN ('share_copy'),NEW.created_at,NEW.created_at,(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')) ON CONFLICT(skill_slug,event_date) DO UPDATE SET total_events=skill_events_daily.total_events+excluded.total_events,views=skill_events_daily.views+excluded.views,install_copies=skill_events_daily.install_copies+excluded.install_copies,saves=skill_events_daily.saves+excluded.saves,compares=skill_events_daily.compares+excluded.compares,outbound_clicks=skill_events_daily.outbound_clicks+excluded.outbound_clicks,claim_starts=skill_events_daily.claim_starts+excluded.claim_starts,claim_submits=skill_events_daily.claim_submits+excluded.claim_submits,resolve_requests=skill_events_daily.resolve_requests+excluded.resolve_requests,install_starts=skill_events_daily.install_starts+excluded.install_starts,install_successes=skill_events_daily.install_successes+excluded.install_successes,install_failures=skill_events_daily.install_failures+excluded.install_failures,agent_calls=skill_events_daily.agent_calls+excluded.agent_calls,outcome_successes=skill_events_daily.outcome_successes+excluded.outcome_successes,outcome_failures=skill_events_daily.outcome_failures+excluded.outcome_failures,share_copies=skill_events_daily.share_copies+excluded.share_copies,first_event_at=min(coalesce(skill_events_daily.first_event_at,excluded.first_event_at),excluded.first_event_at),last_event_at=max(coalesce(skill_events_daily.last_event_at,excluded.last_event_at),excluded.last_event_at),updated_at=(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z');
END;

CREATE TRIGGER skill_events_daily_delete AFTER DELETE ON skill_events BEGIN
 DELETE FROM skill_events_daily WHERE skill_slug=OLD.skill_slug AND event_date=substr(OLD.created_at,1,10);
 INSERT INTO skill_events_daily(skill_slug,event_date,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,first_event_at,last_event_at,updated_at) SELECT skill_slug,substr(OLD.created_at,1,10),count(*),sum(event_type IN ('view')),sum(event_type IN ('install_copy')),sum(event_type IN ('save')),sum(event_type IN ('compare')),sum(event_type IN ('outbound_github','outbound_docs')),sum(event_type IN ('claim_start')),sum(event_type IN ('claim_submit')),sum(event_type IN ('resolve_request')),sum(event_type IN ('install_start')),sum(event_type IN ('install_success')),sum(event_type IN ('install_failure')),sum(event_type IN ('agent_call')),sum(event_type IN ('outcome_success')),sum(event_type IN ('outcome_failure')),sum(event_type IN ('share_copy')),min(created_at),max(created_at),(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')
 FROM skill_events WHERE skill_slug=OLD.skill_slug AND created_at>=substr(OLD.created_at,1,10)||'T00:00:00.000000Z' AND created_at<date(OLD.created_at,'+1 day')||'T00:00:00.000000Z' AND EXISTS(SELECT 1 FROM skills WHERE slug=OLD.skill_slug) GROUP BY skill_slug;
END;

