 FROM skill_events WHERE skill_slug=OLD.skill_slug AND created_at>=substr(OLD.created_at,1,10)||'T00:00:00.000000Z' AND created_at<date(OLD.created_at,'+1 day')||'T00:00:00.000000Z' AND EXISTS(SELECT 1 FROM skills WHERE slug=OLD.skill_slug) GROUP BY skill_slug;
 DELETE FROM skill_events_daily WHERE skill_slug=NEW.skill_slug AND event_date=substr(NEW.created_at,1,10);
 INSERT INTO skill_events_daily(skill_slug,event_date,total_events,views,install_copies,saves,compares,outbound_clicks,claim_starts,claim_submits,resolve_requests,install_starts,install_successes,install_failures,agent_calls,outcome_successes,outcome_failures,share_copies,first_event_at,last_event_at,updated_at) SELECT skill_slug,substr(NEW.created_at,1,10),count(*),sum(event_type IN ('view')),sum(event_type IN ('install_copy')),sum(event_type IN ('save')),sum(event_type IN ('compare')),sum(event_type IN ('outbound_github','outbound_docs')),sum(event_type IN ('claim_start')),sum(event_type IN ('claim_submit')),sum(event_type IN ('resolve_request')),sum(event_type IN ('install_start')),sum(event_type IN ('install_success')),sum(event_type IN ('install_failure')),sum(event_type IN ('agent_call')),sum(event_type IN ('outcome_success')),sum(event_type IN ('outcome_failure')),sum(event_type IN ('share_copy')),min(created_at),max(created_at),(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z')
 FROM skill_events WHERE skill_slug=NEW.skill_slug AND created_at>=substr(NEW.created_at,1,10)||'T00:00:00.000000Z' AND created_at<date(NEW.created_at,'+1 day')||'T00:00:00.000000Z' AND EXISTS(SELECT 1 FROM skills WHERE slug=NEW.skill_slug) GROUP BY skill_slug;
END;

CREATE TRIGGER download_receipt_count AFTER INSERT ON skill_download_receipts BEGIN
 INSERT INTO skill_download_totals(skill_slug,downloads) VALUES(NEW.skill_slug,1)
 ON CONFLICT(skill_slug) DO UPDATE SET downloads=skill_download_totals.downloads+1,updated_at=(strftime('%Y-%m-%dT%H:%M:%f','now') || '000Z');
 UPDATE skills SET site_downloads=(SELECT downloads FROM skill_download_totals WHERE skill_slug=NEW.skill_slug) WHERE slug=NEW.skill_slug;
END;

-- Counters must not rebuild the full-text index on every download.
DROP TRIGGER skills_fts_update;
CREATE TRIGGER skills_fts_update AFTER UPDATE OF slug,name,github_repo,description,tagline,category,long_description,repository ON skills BEGIN
 INSERT INTO skills_fts(skills_fts,rowid,slug,name,github_repo,description,tagline,category,long_description,repository)
 VALUES ('delete',OLD.rowid,OLD.slug,OLD.name,OLD.github_repo,OLD.description,OLD.tagline,OLD.category,OLD.long_description,OLD.repository);
 INSERT INTO skills_fts(rowid,slug,name,github_repo,description,tagline,category,long_description,repository)
 VALUES (NEW.rowid,NEW.slug,NEW.name,NEW.github_repo,NEW.description,NEW.tagline,NEW.category,NEW.long_description,NEW.repository);
END;
